insert into places (id, slug, name_zh, name_ja, category, ward, latitude, longitude, address, nearest_station, age_min, age_max, indoor, rainy_day, free_entry, stroller_score, diaper_score, parking_score, play_score, description, tips, image_url) values
('10000000-0000-4000-8000-000000000001', 'arakawa-nature-park', '荒川自然公园', '荒川自然公園', 'park', '荒川区', 35.7407, 139.7826, '東京都荒川区荒川8丁目25-3', '荒川二丁目站', 1, 10, false, false, true, 4, 3, 2, 5, '有大片绿地、交通园和水边步道，是荒川区经典放电点，适合半天慢慢玩。', '交通园很受欢迎，周末上午更从容；夏天记得带驱蚊和换洗衣物。', 'https://images.unsplash.com/photo-1519331379826-f10be5486c6f?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000002', 'shioiri-park', '汐入公园', '汐入公園', 'park', '荒川区', 35.7353, 139.8112, '東京都荒川区南千住8丁目13-1', '南千住站', 0, 10, false, false, true, 5, 3, 3, 5, '隅田川边的大型公园，视野开阔，草地、 playground 和散步路线都很适合亲子。', '婴儿车推行舒服，傍晚风景好；风大的日子注意保暖。', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000003', 'nippori-minami-park', '日暮里南公园', '日暮里南公園', 'park', '荒川区', 35.7257, 139.7752, '東京都荒川区東日暮里5丁目19', '日暮里站', 1, 8, false, false, true, 4, 2, 1, 3, '车站附近的小型公园，适合顺路短暂停留，给孩子跑一跑、滑一滑。', '空间不算大，更适合饭前饭后的短时间放电。', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000004', 'tenno-park', '天王公园', '天王公園', 'park', '荒川区', 35.738631, 139.795395, '東京都荒川区南千住6丁目67-21', '南千住站', 1, 9, false, false, true, 4, 2, 2, 4, '社区型公园，游具和开放空间平衡，适合附近家庭日常遛娃。', '下午人会多，低龄宝宝建议避开大孩子集中的时段。', 'https://images.unsplash.com/photo-1518156677180-95a2893f3499?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000005', 'ogunohara-park', '尾久之原公园', '尾久の原公園', 'park', '荒川区', 35.7515, 139.7747, '東京都荒川区東尾久7丁目1', '熊野前站', 0, 10, false, false, true, 5, 3, 2, 4, '以广阔草地和蜻蜓池闻名，节奏舒缓，很适合野餐和自然观察。', '草地面积大，带野餐垫体验更好；雨后部分区域会泥泞。', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000006', 'yuinomori-arakawa', 'ゆいの森荒川', 'ゆいの森あらかわ', 'library', '荒川区', 35.7364, 139.7819, '東京都荒川区荒川2丁目50-1', '荒川二丁目站', 0, 10, true, true, true, 5, 5, 2, 3, '图书馆、儿童空间和学习设施结合的亲子友好室内去处，雨天非常实用。', '低龄区安静舒适，适合雨天续航；注意馆内饮食规则。', 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000007', 'arakawa-yuen', '荒川游园', 'あらかわ遊園', 'indoor_play', '荒川区', 35.7513, 139.7588, '東京都荒川区西尾久6丁目35-11', '荒川游园地前站', 1, 8, false, false, false, 4, 4, 3, 5, '复古亲子游乐园，设施温和，对幼儿和小学低年级很友好。', '热门项目可能排队，建议提前确认营业日和门票规则。', 'https://images.unsplash.com/photo-1502136969935-8d8eef54d77b?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000008', 'asukayama-park', '飞鸟山公园', '飛鳥山公園', 'park', '北区', 35.7509, 139.7382, '東京都北区王子1丁目1-3', '王子站', 0, 10, false, false, true, 4, 3, 2, 5, '有大型游具、火车展示和季节花景，是北区代表性的亲子公园。', '小山坡较多，婴儿车建议走缓坡路线；樱花季人流很大。', 'https://images.unsplash.com/photo-1522383225653-ed111181a951?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000009', 'ueno-zoo', '上野动物园', '上野動物園', 'zoo', '台东区', 35.7167, 139.7714, '東京都台東区上野公園9-83', '上野站', 1, 10, false, false, false, 4, 4, 2, 5, '东京经典动物园，动物种类丰富，适合安排半天到一天。', '园区大，提前定好重点路线；午后低龄孩子容易累。', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000010', 'ueno-park', '上野恩赐公园', '上野恩賜公園', 'park', '台东区', 35.7148, 139.7735, '東京都台東区上野公園', '上野站', 0, 10, false, false, true, 4, 3, 2, 4, '公园、美术馆、动物园和池塘集中，适合按天气灵活组合行程。', '周末人多，带娃建议早到；可和动物园或博物馆搭配。', 'https://images.unsplash.com/photo-1557409518-691ebcd96038?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000011', 'national-museum-nature-science', '国立科学博物馆', '国立科学博物館', 'science_museum', '台东区', 35.7163, 139.7765, '東京都台東区上野公園7-20', '上野站', 3, 10, true, true, false, 4, 4, 2, 4, '恐龙、自然科学和互动展示丰富，是雨天或酷暑天的高质量室内选择。', '展馆信息量大，3-6 岁建议只选几个重点区域，不要贪多。', 'https://images.unsplash.com/photo-1566127444979-b3d2b654e3d7?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000012', 'tokyo-national-museum', '东京国立博物馆', '東京国立博物館', 'museum', '台东区', 35.7188, 139.7765, '東京都台東区上野公園13-9', '上野站', 5, 10, true, true, false, 4, 3, 2, 2, '适合对历史、器物和建筑感兴趣的大孩子，空间安静，节奏偏文化体验。', '不建议安排太久，和上野公园散步搭配会更轻松。', 'https://images.unsplash.com/photo-1565060169194-19fabf63012d?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000013', 'sumida-aquarium', '墨田水族馆', 'すみだ水族館', 'aquarium', '墨田区', 35.7101, 139.8107, '東京都墨田区押上1丁目1-2', '押上站', 0, 10, true, true, false, 4, 4, 4, 3, '晴空塔内的城市水族馆，动线紧凑，低龄宝宝也容易看完。', '雨天和假日人流明显，建议避开午后高峰。', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000014', 'tokyo-skytree', '东京晴空塔', '東京スカイツリー', 'landmark', '墨田区', 35.7101, 139.8107, '東京都墨田区押上1丁目1-2', '押上站', 0, 10, true, true, false, 5, 5, 4, 3, '商场、水族馆、观景台和餐饮集中，天气不好时也能安排完整亲子半日。', '商场设施完善，但人多；婴儿车家庭建议预留电梯等待时间。', 'https://images.unsplash.com/photo-1536098561742-ca998e48cbcc?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000015', 'sumida-park', '隅田公园', '隅田公園', 'park', '墨田区', 35.7127, 139.8036, '東京都墨田区向島1丁目', '浅草站', 0, 10, false, false, true, 4, 2, 2, 3, '沿隅田川展开的散步型公园，可以看到晴空塔，适合轻松走走。', '更适合散步拍照，不是强游具型；春季赏樱人很多。', 'https://images.unsplash.com/photo-1505069446780-4ef442b5207f?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000016', 'higashi-shirahige-park', '东白鬚公园', '東白鬚公園', 'park', '墨田区', 35.7311, 139.8157, '東京都墨田区堤通2丁目2', '钟淵站', 1, 10, false, false, true, 4, 3, 3, 4, '沿河大型公园，跑跳空间充足，适合自行车、散步和季节性活动。', '园区较长，先确认入口和目的区域，避免孩子走太累。', 'https://images.unsplash.com/photo-1473773508845-188df298d2d1?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000017', 'adachi-park-of-living-things', '足立区生物园', '足立区生物園', 'zoo', '足立区', 35.7844, 139.8003, '東京都足立区保木間2丁目17-1', '竹之塚站', 1, 10, true, true, false, 4, 4, 3, 4, '规模不大但内容密度高，可以近距离观察昆虫、小动物和水生生物。', '很适合幼儿第一次动物观察，和附近公园搭配更充实。', 'https://images.unsplash.com/photo-1551189014-fe516aed0e9e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000018', 'toneri-park', '舍人公园', '舎人公園', 'park', '足立区', 35.7967, 139.7707, '東京都足立区舎人公園1-1', '舎人公园站', 0, 10, false, false, true, 5, 3, 5, 5, '足立区大型都立公园，草地、水边、游具和烧烤区丰富，适合一整天。', '面积很大，建议定一个集合点；开车家庭相对友好。', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000019', 'adachi-urban-agricultural-park', '都市农园足立', '足立区都市農業公園', 'park', '足立区', 35.7852, 139.7398, '東京都足立区鹿浜2丁目44-1', '西新井大师西站', 1, 10, false, false, true, 4, 3, 4, 4, '能接触农作物、花田和自然景观，适合想让孩子体验季节感的家庭。', '活动和花期会变化，出发前查一下官方日程更稳。', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000020', 'kita-central-park', '北区中央公园', '北区中央公園', 'park', '北区', 35.7589, 139.7229, '東京都北区十条台1丁目2-1', '十条站', 0, 10, false, false, true, 4, 3, 3, 4, '绿地宽敞，氛围安静，适合散步、野餐和日常消耗体力。', '树荫不错，夏天也相对舒服；游具区和草地区可分开安排。', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000021', 'otonashi-shinsui-park', '音无亲水公园', '音無親水公園', 'river', '北区', 35.7547, 139.7385, '東京都北区王子本町1丁目', '王子站', 2, 10, false, false, true, 3, 2, 1, 3, '小而有特色的亲水空间，适合夏季短时间玩水和散步。', '石阶和水边较多，低龄孩子需要牵好；带毛巾和备用鞋。', 'https://images.unsplash.com/photo-1437482078695-73f5ca6c96e2?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000022', 'oji-children-center', '王子儿童馆', '王子児童館', 'children_center', '北区', 35.7558, 139.7367, '東京都北区王子2丁目7', '王子站', 0, 6, true, true, true, 4, 4, 1, 3, '适合低龄孩子的室内公共空间，雨天、酷暑或寒冷天气可作为稳定备选。', '初次去建议带在留相关证件，确认开放时间和适用年龄。', 'https://images.unsplash.com/photo-1503454537195-1dcabb73ffb9?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000023', 'arakawa-children-family-center', '荒川儿童家庭中心', '荒川子ども家庭総合センター', 'children_center', '荒川区', 35.736, 139.7832, '東京都荒川区荒川1丁目50', '荒川区役所前站', 0, 6, true, true, true, 4, 4, 1, 3, '面向亲子和育儿家庭的公共设施，适合低龄宝宝活动和家长获取育儿信息。', '具体活动多按日期变化，去之前看一下区官网通知。', 'https://images.unsplash.com/photo-1564429097439-e400382dc893?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000024', 'minamisenju-children-center', '南千住儿童馆', '南千住児童館', 'children_center', '荒川区', 35.7338, 139.7997, '東京都荒川区南千住', '南千住站', 0, 8, true, true, true, 4, 4, 1, 3, '社区型儿童馆，适合雨天补位和低龄孩子短时间室内活动。', '公共设施规则会因年龄段不同，初次使用先问工作人员最省心。', 'https://images.unsplash.com/photo-1542810634-71277d95dcbb?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000025', 'machiya-library', '町屋图书馆', '町屋図書館', 'library', '荒川区', 35.7429, 139.7813, '東京都荒川区町屋5丁目11', '町屋站', 0, 10, true, true, true, 4, 3, 1, 2, '安静的社区图书馆，适合亲子阅读、借绘本和雨天短暂停留。', '更偏阅读不偏放电，适合和附近公园组合。', 'https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000026', 'arakawa-riverside', '荒川河川敷', '荒川河川敷', 'river', '足立区', 35.7667, 139.7902, '東京都足立区千住周辺', '北千住站', 2, 10, false, false, true, 4, 1, 3, 4, '开阔河川地，适合骑车、跑步、放风筝和大孩子释放体力。', '遮阴和厕所位置要提前确认；风大时体感温度会低。', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000027', 'shioiri-waterfront', '汐入亲水空间', '汐入親水広場', 'river', '荒川区', 35.7361, 139.8092, '東京都荒川区南千住8丁目', '南千住站', 1, 10, false, false, true, 4, 2, 2, 3, '靠近汐入公园的水边散步空间，适合推车散步和看船。', '可和汐入公园合并成一条轻松路线，低龄孩子注意水边安全。', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000028', 'taito-children-center', '台东儿童馆', '台東児童館', 'children_center', '台东区', 35.712, 139.7839, '東京都台東区台東', '新御徒町站', 0, 8, true, true, true, 4, 4, 1, 3, '台东区内适合亲子使用的室内儿童空间，适合作为雨天附近备选。', '公共儿童馆常有使用登记和时间段规则，初访前建议确认。', 'https://images.unsplash.com/photo-1503454537195-1dcabb73ffb9?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000029', 'sumida-children-center', '墨田儿童馆', 'すみだ児童館', 'children_center', '墨田区', 35.7108, 139.8015, '東京都墨田区', '本所吾妻桥站', 0, 8, true, true, true, 4, 4, 1, 3, '社区亲子活动空间，适合小朋友室内活动和家长临时避雨休整。', '适合安排在晴空塔、隅田公园周边行程的补充点。', 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000030', 'kita-children-center', '北区儿童馆', '北区児童館', 'children_center', '北区', 35.7581, 139.735, '東京都北区', '王子站', 0, 8, true, true, true, 4, 4, 1, 3, '北区家庭常用的室内儿童活动备选，适合天气不稳定时安排。', '和飞鸟山、王子周边路线组合，能让一天更有弹性。', 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000031', 'shinjuku-central', '新宿中央公园', '新宿中央公園', 'park', '新宿区', 35.689, 139.691, '東京都新宿区', '都厅前站', 1, 12, false, false, true, 4, 4, 3, 5, '游具区大型滑梯，戏水便。', '都厅观景台顺路一站。', 'https://images.unsplash.com/photo-1547407139-3c921a66005c?auto=format&fit=crop&w=400&q=80'),
('10000000-0000-4000-8000-000000000032', 'miyashita', '宫下公园', 'MIYASHITA PARK', 'park', '涩谷区', 35.661, 139.701, '東京都渋谷区', '涩谷站', 2, 15, false, false, true, 5, 5, 4, 4, '空中操场，潮流地标。', '楼下有Babyroom，极其贴心。', 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=400&q=80'),
